+static void terminal_gen_id(char *id)
+  FUNC_ATTR_NONNULL_ALL
+{
+  uint8_t buf[TERM_ID_RAW_BYTES];
+  if (uv_random(NULL, NULL, buf, sizeof(buf), 0, NULL) != 0) {
