+static void terminal_append_sgr(StringBuilder *out, const VTermScreenCell *cell, VTermState *state)
+  FUNC_ATTR_NONNULL_ALL
+{
+  kv_concat(*out, "\x1b[0");
+  if (cell->attrs.bold) {
