+  case VTERM_UNDERLINE_CURLY:
+    kv_concat(*out, ";4:3");
+    break;
+  case VTERM_UNDERLINE_OFF:
+    break;
+  }
+  if (cell->attrs.blink) {
+    kv_concat(*out, ";5");
+  }
+  if (cell->attrs.reverse) {
+    kv_concat(*out, ";7");
+  }
+  if (cell->attrs.conceal) {
+    kv_concat(*out, ";8");
+  }
+  if (cell->attrs.strike) {
+    kv_concat(*out, ";9");
+  }
+  if (cell->attrs.font) {
