+  VTermColor rgb = *color;
+  vterm_state_convert_color_to_rgb(state, &rgb);
+  kv_printf(*out, ";%d;2;%d;%d;%d", is_fg ? 38 : 48, rgb.rgb.red, rgb.rgb.green, rgb.rgb.blue);
