+          if (!cell_is_blank(&cell)) {
+            empty = false;
+            break;
+          }
+        }
+        if (!empty) {
+          break;
+        }
+        last_row--;
+      }
+      // Screen row 0 = buffer line 1
+      end = (linenr_T)last_row + 1;
+    }
+  }
