comment_data.body:
instead of making `struct terminal` "public", can we keep it here, but expose an "iterator" from `terminal.c`? That eliminates the `terminal_defs.h` hoist.

benefits:

- encapsulates the scrollback indexing. (this avoids bugs)

sketch (AI-generated, but LGTM. especially the callback-based interface):

`terminal.c`:

```c
  /// Called once per logical line. `cells`/`cols` are owned by the caller and
  /// valid only for the duration of the call.
  typedef void (*TerminalRowCb)(const VTermScreenCell *cells, size_t cols, void *data);

  /// Walk a terminal's logical lines [start, end] (1-based, inclusive): scrollback
  /// (oldest first) followed by the visible screen. end == 0 means "to the last line".
  void terminal_foreach_row(Terminal *term, linenr_T start, linenr_T end, TerminalRowCb cb, void *data)
    FUNC_ATTR_NONNULL_ARG(1, 4);
  {
    int height, width;
    vterm_get_size(term->vt, &height, &width);
    linenr_T total = (linenr_T)term->sb_current + height;
    if (end == 0 || end > total) {
      end = total;
    }
    start = MAX(start, 1);  // clamp once, here (fixes the scrollback OOB)

    VTermScreenCell *screen_row = xmalloc(sizeof(*screen_row) * (size_t)width);
    for (linenr_T lnum = start; lnum <= end; lnum++) {
      if (lnum <= (linenr_T)term->sb_current) {
        // Scrollback: line 1 = oldest = sb_buffer[sb_current - 1].
        ScrollbackLine *line = term->sb_buffer[term->sb_current - (size_t)lnum];
        cb(line->cells, line->cols, data);
      } else {
        // Visible screen: line sb_current+1 = row 0.
        int row = (int)(lnum - (linenr_T)term->sb_current - 1);
        for (int col = 0; col < width; col++) {
          vterm_screen_get_cell(term->vts, (VTermPos){ .row = row, .col = col }, &screen_row[col]);
        }
        cb(screen_row, (size_t)width, data);
      }
    }
    xfree(screen_row);
  }

  /// Convert an indexed color to RGB using the terminal's palette.
  void terminal_color_to_rgb(Terminal *term, VTermColor *color)
    FUNC_ATTR_NONNULL_ALL;
  {
    vterm_state_convert_color_to_rgb(vterm_obtain_state(term->vt), color);
  }
```

`terminal_encode.c`:

```c
  typedef struct {
    Terminal *term;
    StringBuilder *out;
  } TeEncodeCtx;

  static void te_encode_row_cb(const VTermScreenCell *cells, size_t cols, void *data)
  {
    TeEncodeCtx *ctx = data;
    te_encode_line2ansi(ctx->term, cells, cols, ctx->out);
  }

  String te_encode_export_ansi(Terminal *term, int start, int end)
    FUNC_ATTR_NONNULL_ALL FUNC_ATTR_WARN_UNUSED_RESULT
  {
    StringBuilder out = KV_INITIAL_VALUE;
    TeEncodeCtx ctx = { .term = term, .out = &out };
    terminal_foreach_row(term, start, end, te_encode_row_cb, &ctx);

    kv_concat(out, "\x1b[0m");
    kv_push(out, NUL);
    return (String){ .data = out.items, .size = --out.size };
  }

```

